import React, { useId } from 'react';

interface MuscleIconProps {
  size?: number;
}

// Shared gradient and filter definitions
const MuscleGradient: React.FC<{ id: string }> = ({ id }) => (
  <defs>
    <linearGradient id={id} x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stopColor="#ff6b35" />
      <stop offset="50%" stopColor="#f7418c" />
      <stop offset="100%" stopColor="#fc5c7d" />
    </linearGradient>
    <filter id={`${id}Shadow`} x="-20%" y="-20%" width="140%" height="140%">
      <feDropShadow dx="0" dy="2" stdDeviation="2" floodColor="#f7418c" floodOpacity="0.3" />
    </filter>
  </defs>
);

